class OrderedStream {
public:
    vector<string> stream;
    int ptr;
    OrderedStream(int n) : stream(n + 2, ""), ptr(1) {}
    vector<string> insert(int idKey, string value) {
        stream[idKey] = value;
        vector<string> res;
        while (!stream[ptr].empty()) {
            res.push_back(stream[ptr]);
            ptr++;
        }
        return res;
    }
};

class OrderedStream {
    private String[] stream;
    private int ptr;
    public OrderedStream(int n) {
        stream = new String[n + 2];
        ptr = 1;
    }
    public List<String> insert(int idKey, String value) {
        stream[idKey] = value;
        List<String> res = new ArrayList<>();
        while (stream[ptr] != null) {
            res.add(stream[ptr]);
            ptr++;
        }
        return res;
    }
}

var OrderedStream = function(n) {
    this.stream = new Array(n + 2).fill(null);
    this.ptr = 1;
};

OrderedStream.prototype.insert = function(idKey, value) {
    this.stream[idKey] = value;
    const res = [];
    while (this.stream[this.ptr] !== null) {
        res.push(this.stream[this.ptr]);
        this.ptr++;
    }
    return res;
};
